<div class="module-intro"><div><span class="eyebrow">REGISTROS OPERACIONAIS</span><h2>Sinistros de trânsito</h2><p>Registro, consulta e acompanhamento das ocorrências.</p></div><?php if($canCreate): ?><button class="btn primary" data-toggle-target="accident-form">＋ Novo sinistro</button><?php endif; ?></div>
<form method="get" class="filter-bar"><input name="q" placeholder="Protocolo, local ou bairro" value="<?= e($filters['q']) ?>"><select name="type"><option value="">Todos os tipos</option><?php foreach(['Colisão','Atropelamento','Queda de motocicleta','Capotamento','Choque contra objeto fixo','Engavetamento','Danos materiais','Outros'] as $t): ?><option <?= $filters['type']===$t?'selected':'' ?>><?= e($t) ?></option><?php endforeach; ?></select><input type="date" name="from" value="<?= e($filters['from']) ?>"><input type="date" name="to" value="<?= e($filters['to']) ?>"><button class="btn subtle">Filtrar</button></form>
<?php if($canCreate||$editAccident): ?><form id="accident-form" class="panel form-panel <?= $editAccident?'':'hidden' ?>" method="post" action="<?= e($baseUrl) ?>/sinistro/salvar" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)($editAccident['id']??0) ?>"><div class="section-heading"><div><h3><?= $editAccident?'Editar sinistro '.e($editAccident['protocol']):'Novo registro de sinistro' ?></h3><p>Os campos marcados são obrigatórios.</p></div></div><div class="form-grid"><label>Data da ocorrência *<input type="date" name="occurred_date" required value="<?= $editAccident?date('Y-m-d',strtotime($editAccident['occurred_at'])):date('Y-m-d') ?>"></label><label>Horário *<input type="time" name="occurred_time" required value="<?= $editAccident?date('H:i',strtotime($editAccident['occurred_at'])):date('H:i') ?>"></label><label>Classificação *<select name="accident_type" required><option value="">Selecione</option><?php foreach(['Colisão','Atropelamento','Queda de motocicleta','Capotamento','Choque contra objeto fixo','Engavetamento','Danos materiais','Outros'] as $t): ?><option <?= ($editAccident['accident_type']??'')===$t?'selected':'' ?>><?= e($t) ?></option><?php endforeach; ?></select></label><label>Local *<input name="location" required maxlength="180" value="<?= e($editAccident['location']??'') ?>"></label><label>Endereço<input name="address" maxlength="255" value="<?= e($editAccident['address']??'') ?>"></label><label>Bairro<input name="neighborhood" maxlength="120" value="<?= e($editAccident['neighborhood']??'') ?>"></label><label>Ponto de referência<input name="reference_point" value="<?= e($editAccident['reference_point']??'') ?>"></label><label>Tipo de via<input name="road_type" value="<?= e($editAccident['road_type']??'') ?>"></label><label>Condições climáticas<input name="weather" value="<?= e($editAccident['weather']??'') ?>"></label><label class="full">Descrição detalhada *<textarea name="description" rows="3" required><?= e($editAccident['description']??'') ?></textarea></label></div>
<div class="check-row"><?php foreach(['has_victims'=>'Houve vítimas','has_injuries'=>'Houve feridos','has_fatalities'=>'Houve óbitos','public_property_damage'=>'Dano ao patrimônio público','signage_damage'=>'Dano à sinalização','needs_external_support'=>'Necessitou apoio externo'] as $k=>$v): ?><label><input type="checkbox" name="<?= $k ?>" <?= !empty($editAccident[$k])?'checked':'' ?>> <?= e($v) ?></label><?php endforeach; ?></div>
<div class="form-grid"><label class="full">Detalhes do apoio externo<input name="external_support_notes" maxlength="255" value="<?= e($editAccident['external_support_notes']??'') ?>" placeholder="Órgão acionado, equipe de apoio, protocolo..."></label><label class="full">Observações internas<textarea name="notes" rows="2"><?= e($editAccident['notes']??'') ?></textarea></label></div>
<div class="section-heading"><div><h3>Equipe de atendimento</h3><p>Servidores que participaram do atendimento.</p></div></div><fieldset><div class="staff-checks"><?php foreach($staff as $s): ?><label><input type="checkbox" name="responsible_ids[]" value="<?= (int)$s['id'] ?>" <?= in_array((int)$s['id'],$editAccident['staff']??[],true)?'checked':'' ?>> <?= e($s['name']) ?></label><?php endforeach; ?></div></fieldset>
<div class="section-heading"><div><h3>Veículos envolvidos</h3><p>Adicione um veículo por vez.</p></div><button type="button" class="btn subtle" data-add-row="vehicles">＋ Veículo</button></div><div id="vehicles" class="repeat-list"><?php $vehicleRows=$editAccident['vehicles']??[[]]; foreach($vehicleRows as $i=>$v): ?><div class="repeat-row"><input name="vehicles[<?= $i ?>][plate]" placeholder="Placa" value="<?= e($v['plate']??'') ?>"><input name="vehicles[<?= $i ?>][brand]" placeholder="Marca" value="<?= e($v['brand']??'') ?>"><input name="vehicles[<?= $i ?>][model]" placeholder="Modelo" value="<?= e($v['model']??'') ?>"><input name="vehicles[<?= $i ?>][color]" placeholder="Cor" value="<?= e($v['color']??'') ?>"><input name="vehicles[<?= $i ?>][driver_name]" placeholder="Condutor" value="<?= e($v['driver_name']??'') ?>"><input name="vehicles[<?= $i ?>][damage_notes]" placeholder="Danos identificados" value="<?= e($v['damage_notes']??'') ?>"><input type="file" name="vehicle_photos_<?= $i ?>[]" accept="image/jpeg,image/png,image/webp" multiple></div><?php endforeach; ?></div>
<div class="section-heading"><div><h3>Pessoas envolvidas</h3><p>Condutores, passageiros, pedestres e demais envolvidos.</p></div><button type="button" class="btn subtle" data-add-row="people">＋ Pessoa</button></div><div id="people" class="repeat-list"><?php foreach(($editAccident['people']??[]) as $i=>$v): ?><div class="repeat-row"><input name="people[<?= $i ?>][full_name]" placeholder="Nome completo" value="<?= e($v['full_name']) ?>"><input name="people[<?= $i ?>][document_ref]" placeholder="Documento" value="<?= e($v['document_ref']) ?>"><select name="people[<?= $i ?>][involvement]"><option><?= e($v['involvement']) ?></option><option>Condutor</option><option>Passageiro</option><option>Pedestre</option><option>Outro</option></select><input name="people[<?= $i ?>][contact]" placeholder="Contato" value="<?= e($v['contact']) ?>"><input name="people[<?= $i ?>][notes]" placeholder="Observações" value="<?= e($v['notes']) ?>"><button type="button" class="btn tiny danger-btn" data-remove-row>Remover</button></div><?php endforeach; ?></div>
<div class="section-heading"><div><h3>Testemunhas</h3><p>Limite máximo de quatro testemunhas.</p></div><button type="button" class="btn subtle" data-add-row="witnesses" data-max="4">＋ Testemunha</button></div><div id="witnesses" class="repeat-list"><?php foreach(($editAccident['witnesses']??[]) as $i=>$v): ?><div class="repeat-row"><input name="witnesses[<?= $i ?>][name]" placeholder="Nome" value="<?= e($v['name']) ?>"><input name="witnesses[<?= $i ?>][contact]" placeholder="Contato" value="<?= e($v['contact']) ?>"><input name="witnesses[<?= $i ?>][notes]" placeholder="Observações" value="<?= e($v['notes']) ?>"><button type="button" class="btn tiny danger-btn" data-remove-row>Remover</button></div><?php endforeach; ?></div>
<div class="form-grid"><label class="full">Documentos e imagens (JPG, PNG, WEBP ou PDF)<input type="file" name="attachments[]" accept="image/jpeg,image/png,image/webp,application/pdf" multiple></label></div><div class="section-heading"><div><h3>Confirmação do servidor</h3><p>Assinatura interna de confirmação, não equivale a certificado digital.</p></div><button type="button" class="btn subtle" data-clear-signature>Limpar assinatura</button></div><canvas id="signature-pad" class="signature-pad" width="900" height="180"></canvas><input type="hidden" name="signature_data" id="signature-data"><div class="form-actions"><button class="btn primary"><?= $editAccident?'Atualizar sinistro':'Salvar sinistro' ?></button><button type="button" class="btn subtle" data-toggle-target="accident-form">Cancelar</button></div></form><?php endif; ?>
<section class="panel"><div class="section-heading"><div><h3>Registros encontrados</h3><p><?= count($accidents) ?> registros nesta consulta</p></div></div><?php if(!$accidents): ?><div class="table-empty">Nenhum sinistro encontrado com os filtros informados.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Protocolo</th><th>Data e hora</th><th>Local</th><th>Classificação</th><th>Situação</th><th></th></tr></thead><tbody><?php foreach($accidents as $a): ?><tr><td><b><?= e($a['protocol']) ?></b></td><td><?= date('d/m/Y H:i',strtotime($a['occurred_at'])) ?></td><td><?= e($a['location']) ?><?= $a['neighborhood']?' · '.e($a['neighborhood']):'' ?></td><td><?= e($a['accident_type']) ?></td><td><span class="state-pill"><?= e($a['status']) ?></span></td><td><a class="text-link" href="<?= e($baseUrl) ?>/sinistro/<?= (int)$a['id'] ?>">Abrir →</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>